void register_embedded_modules(sol::state& lua) {

  lua.safe_script(R"(
    function __has_module__(name)
      local __p__, __m__ = pcall(require, name);
      if __p__ then
        return true
      else
        return false
      end
    end
  )");

  sol::function module_exists = lua["__has_module__"];

  lua.add_package_loader(embedded_loader);

}

